var DATA = {"measurand": "Mass of test weight", "comps": "repeatability=0.0002|calibration=0.0005", "method": "Root-sum-square", "k": "2"};
console.log("Measurand: " + DATA.measurand + " | Combination: " + DATA.method);
var comps = DATA.comps.split("|").map(function (s) { return s.trim(); });
var ss = 0;
console.log("Uncertainty components:");
comps.forEach(function (c) {
  var m = c.match(/([\w ]+?)\s*=\s*([0-9.]+)/);
  if (m) {
    var u = parseFloat(m[2]);
    ss += u * u;
    console.log("  " + m[1].trim() + ": u=" + u);
  } else console.log("  " + c);
});
var uc = Math.sqrt(ss), k = parseFloat(DATA.k) || 2, U = k * uc;
console.log("Combined standard uncertainty: uc=" + uc.toFixed(4));
console.log("Expanded uncertainty: U=" + U.toFixed(4) + " (k=" + k + ")");
console.log("RESULT: uncertainty budget combined in quadrature.");

